#include <iostream>

int main() {
    int a[5] = {10, 20, 30, 40, 50};
    int* p = a;
    int* q = &a[3];

    // 1. Precedence demo
    int val1 = *p++;       // yields a[0] (10), p advances to a[1]
    int val2 = *(++p);     // p advances to a[2], yields a[2] (30)
    (*p)++;                // a[2] becomes 31

    std::cout << "val1: " << val1 << "\n";
    std::cout << "val2: " << val2 << "\n";
    std::cout << "a[2]: " << a[2] << "\n";

    // 2. Pointer subtraction and comparisons
    std::cout << "q - p: " << (q - p) << "\n";
    std::cout << "p < q: " << (p < q) << "\n";
    std::cout << "p + 1 == q: " << (p + 1 == q) << "\n";

    return 0;
}

#include <iostream>
#include <new>
#include <cstdlib>

int main() {
    int n = 5;
    // Allocate dynamic array using std::nothrow to safely check for nullptr
    int* head = new (std::nothrow) int[n];
    if (head == nullptr) {
        std::cout << "Khong du bo nho\n";
        std::exit(0);
    }

    // Populate array elements using simulated inputs
    int values[5] = {42, 15, 88, 3, 27};
    for (int* p = head; p < head + n; ++p) {
        *p = values[p - head];
    }

    // Bubble sort using pointer arithmetic as shown on Page 92
    for (int* p = head; p < head + n - 1; ++p) {
        for (int* q = p + 1; q < head + n; ++q) {
            if (*q < *p) {
                int temp = *p;
                *p = *q;
                *q = temp;
            }
        }
    }

    // Display sorted values
    for (int* p = head; p < head + n; ++p) {
        std::cout << *p << " ";
    }
    std::cout << "\n";

    // Release dynamic array buffer
    delete[] head;
    head = nullptr;

    return 0;
}

#include <iostream>

int main() {
    const int SIZE = 4;
    int a[SIZE] = {100, 200, 300, 400};
    int* p = a; // p points to &a[0]

    std::cout << "Base address check: " << (p == &a[0]) << "\n";

    for (int i = 0; i < SIZE; ++i) {
        // Demonstrating that a[i], *(a + i), *(p + i), and p[i] are all identical
        std::cout << "Index " << i << ": "
                  << a[i] << " == "
                  << *(a + i) << " == "
                  << *(p + i) << " == "
                  << p[i] << "\n";
    }

    return 0;
}
